create table bldg_directory (
    building_id        number
        generated by default on null as identity
    not null enable,
    fk_facility_id     number,
    encounter_org      varchar2(4000 char),
    aff_fac_pool_alias varchar2(4000 char),
    cluster_           varchar2(4000 char),
    bldg_disp          varchar2(4000 char),
    bldg_desc          varchar2(4000 char)
);

alter table bldg_directory
    add constraint facility_disp_id_pk primary key ( building_id )
        using index enable;


